                return (is_match(i, j + 2) or (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return first_match and (is_match(i + 1, j) or is_match(i + 1, j + 2))
        else:
            if first_match:
                return is_match(i + 1, j + 1)

        return False

    return is_match(0, 0)

